import {showAdminRecovery,showUserRecovery} from './admin-recovery-download.mjs';
const adminMode=location.pathname.endsWith('/admin.html');
import {briefIntelligencePage,bindBriefIntelligence} from './brief-intelligence.mjs';
import {IQLedgerClient,IQPendingAction} from './iq-client.mjs?v=shared-1';
const api=new IQLedgerClient(), main=document.querySelector('#main');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iq=n=>`${(Number(n||0)/100).toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} <small>IQ</small>`;
const uid=()=>crypto.randomUUID();
let analystState={business:{campaigns:[],reports:[],fullReports:[]}};
let savedReportIDs=new Set();
let attempted=false;
let inbox={items:[],unread:0,through:0},notificationCursor=null;
let session, wallet, markets=[], views=[], studies=[], view, generation=0, pending=null;
const heading=(title,text='')=>`<div class="heading"><div><div class="eyebrow">SHARED SIMULATION · TEST IQ ONLY</div><h1>${esc(title)}</h1><p>${esc(text)}</p></div></div>`;
const stats=items=>`<div class="stats">${items.map(([label,value])=>`<div class="stat"><span class="stat-label">${esc(label)}</span><strong>${value}</strong></div>`).join('')}</div>`;
const panel=(title,body)=>`<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2></div><div class="panel-body">${body}</div></section>`;
const empty=text=>`<p class="muted">${esc(text)}</p>`;
const options=values=>values.map(v=>`<option>${esc(v)}</option>`).join('');
const profileOptions={gender:['Women','Men','Other'],age:['18–29','30–44','45+'],city:['London','Manchester','Birmingham','Bristol'],income:['Under £50k','£50k–£99k','£100k+']};
const profiles=(all=false)=>Object.entries(profileOptions).map(([k,v])=>`<label>${esc(k)}<select name="${k}">${options(all?['All',...v]:v)}</select></label>`).join('');
const notice=text=>`<div class="notice">${esc(text)}</div>`;
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),6000);}
function error(e){toast(e.message);if(e.status===401){session=null;login();}}
function notificationBadge(){const badge=document.querySelector('#notification-link');if(badge){badge.hidden=!session;badge.textContent=`Notifications${inbox.unread?' ('+inbox.unread+')':''}`;badge.setAttribute('aria-label',`${inbox.unread} unread notifications`);}}
function chrome(){document.querySelectorAll('[data-nav=operations],[data-nav=launch]').forEach(e=>e.hidden=!adminMode||!session?.operator);const adminLink=document.querySelector('#admin-link');if(adminLink)adminLink.hidden=!session?.operator;notificationBadge();document.querySelector('#header-balance').innerHTML=wallet?iq(wallet.available_units).replace(' <small>IQ</small>',''):'—';document.querySelector('.avatar').textContent=(session?.username||session?.subject)?.slice(0,2).toUpperCase()||'IQ';document.querySelector('.avatar').title=session?.username||session?.subject||'Shared demo';document.querySelector('#positions-count').textContent=views.flatMap(v=>v.positions).filter(p=>p.quantity>0).length;}
let authMode='login',adminRecoverMode=false;
function login(){if(adminMode&&adminRecoverMode){main.innerHTML=heading('Recover administrator access','Use your private admin recovery key. Normal user recovery keys will not work here.')+panel('Set a new admin password',`<form id="admin-recover" class="admin-password-form"><label>Admin username<input name="username" autocomplete="username" required maxlength="30"></label><label>Admin recovery key<input name="recovery_key" type="password" autocomplete="off" required minlength="20" maxlength="160"></label><label>New admin password<input name="new_password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><label>Confirm new admin password<input name="confirm_password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><p class="fine">At least 15 characters. This ends all admin sessions and replaces your recovery key. Save the replacement shown after recovery.</p><div id="admin-recover-error" class="error" role="alert"></div><button class="button">Reset admin password</button></form><button class="outline" data-admin-recover="back">Back to admin login</button><p>No email is sent. Your initial recovery key is in the private admin recovery file on your laptop. If you have lost both your password and key, recovery requires local setup on the host laptop.</p>`);return;}if(adminMode){chrome();main.innerHTML=heading('Administrator sign-in','Private operations workspace · simulated exchange')+panel('Admin access',`<form id="admin-login"><label>Admin username<input name="username" autocomplete="username" required maxlength="30" placeholder="Your admin username"></label><label>Admin password<input type="password" name="password" required autocomplete="current-password" maxlength="128"></label><button class="button">Sign in as administrator</button></form><button class="outline" data-admin-recover="open">Forgot admin password?</button><p>Administrator credentials are separate from demo user accounts. No public admin signup. Use your private admin recovery key if you forget your password.</p><a href="/exchange/">Go to user login</a>`);return;}inbox={items:[],unread:0,through:0};notificationCursor=null;const signup=authMode==='signup',recover=authMode==='recover',invite=authMode==='invite';main.innerHTML=heading(signup?'Join the demo exchange':recover?'Recover your account':'Welcome to INTUITION','One account for trading, paid research and your shared IQ wallet.')+`<div class="auth-layout"><section class="panel panel-body auth-card"><div class="segmented"><button type="button" data-auth="login" class="${!signup?'active':''}">Log in</button><button type="button" data-auth="signup" class="${signup?'active':''}">Create account</button></div><h2>${signup?'Create your demo account':recover?'Set a new password':invite?'Demo access code':'Log in to your account'}</h2><form id="${invite?'login':'account-auth'}" data-mode="${authMode}">${invite?'<label>Private access code<input name="access_code" type="password" autocomplete="off" required minlength="20"></label>':`<label>Username<input name="username" autocomplete="username" minlength="3" maxlength="30" pattern="[A-Za-z0-9_]{3,30}" required placeholder="Choose a username"></label>${recover?'<label>Recovery key<input name="recovery_key" type="password" autocomplete="off" required></label>':''}<label>${recover?'New password':'Password'}<input name="password" type="password" autocomplete="${signup||recover?'new-password':'current-password'}" minlength="${signup||recover?15:1}" maxlength="128" required></label>${signup||recover?'<p class="fine">At least 15 characters. A few unrelated words make a memorable password.</p><label>Confirm password<input name="confirm_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label>':''}`}
<div role="alert" class="error" id="auth-error"></div><button class="button">${signup?'Create demo account':recover?'Reset password':'Log in'}</button></form><div class="auth-links"><button class="outline" data-auth="recover">Forgot password?</button><button class="outline" data-auth="invite">Demo access code</button><a href="/exchange/admin.html">Administrator sign-in</a></div><p class="fine">Your account is stored on the shared demo server. No email address is required. Keep the recovery key shown after sign-up somewhere private.</p></section><aside class="panel panel-body"><span class="tag blue">SIMULATED ONLY</span><h2>Try it with 1,000 test IQ.</h2><p>Explore shared markets, buy and sell shares, and earn more test IQ for accepted research.</p><p>You can also create a fictional research brief and pay participants from your demo wallet.</p><p>Test IQ has no cash value. There are no deposits, withdrawals or guaranteed returns. Use fictional research responses and profiles.</p></aside></div>`;wallet=null;chrome();}
function recoveryNotice(username,key,signup){pending=null;attempted=false;showUserRecovery(document.querySelector('#dialog'),username,key,signup);}

let welcomeState={},guidedMarket=null;
async function startSession(){if(session.operator&&!adminMode){location.replace('/exchange/admin.html#admin');return;}if(adminMode){if(!session.operator){chrome();main.innerHTML=heading('Admin account required')+notice('You are signed in as a demo user. Sign out to use your administrator account.')+'<button class="button" data-logout>Sign out</button> <a href="/exchange/">Return to exchange</a>';return;}if(!location.hash)location.hash='admin';return render();}welcomeState=await api.request('/welcome');if(welcomeState.show_on_login)location.hash='welcome';await render();}
function welcomePage(){
 const market=views.find(v=>v.market.status==='open'&&!v.bitcoin&&v.order_book.length)||views.find(v=>v.market.status==='open');
 const brief=studies.find(s=>!s.mine&&s.status==='open'&&!s.responses.length&&s.reserved>=s.reward+Math.round(s.reward*.25));
 return heading(`Welcome, ${session.username||session.subject}`,'Try the exchange at your own pace. Everything here uses simulated IQ.')+`<div class="welcome-hero panel panel-body"><div><span class="tag blue">YOUR DEMO STARTING BALANCE</span><h2>1,000 <small>test IQ</small>. Room to explore.</h2><p>IQ is the unit you use for demo trades and research. Your starter allocation is given once. It is not money, cannot be withdrawn and is not topped up when you reopen this guide.</p><p><b>Available now: ${iq(wallet.available_units)}</b> · Reserved: ${iq(wallet.reserved_units)}</p></div><a class="outline" href="#wallet">See your wallet</a></div><div class="welcome-grid">${panel('Understand your IQ',`<p><b>Available IQ</b> is ready to use. <b>Reserved IQ</b> is held for waiting buy orders or a research budget.</p><p>A matched trade can gain or lose test IQ. Cancelling an unfilled order releases its reserved IQ.</p><p class="fine">No deposits, withdrawals or real-money rewards.</p>`)}${panel(welcomeState.traded?'First trade completed':'Try your first trade',`<p>Choose Yes or No on a question. Start with <b>5 shares</b>—at most 4.95 test IQ at the highest allowed price.</p><p>Preview shows what can fill now, what will wait, and your potential payout and profit after the settlement fee. Losing shares pay zero.</p>${market?`<p><b>${esc(market.market.question)}</b></p><button class="button" data-guided-market="${esc(market.market.id)}">${welcomeState.traded?'Explore another trade':'Preview a small trade'}</button>`:empty('No open markets yet. Check back when an operator publishes one.')}<p class="fine">You choose the outcome and confirm. A waiting order is not a completed trade.</p>`)}${panel(welcomeState.research_paid?'Research reward received':welcomeState.research_submitted?'Research submitted':'Try paid research',`<p>Read a brief, check who it is for, and describe a <b>fictional experience</b>. Use a fictional profile for this demo.</p><p>The buyer reviews your response. Accepted work is paid from their reserved budget into the same IQ wallet you trade with. Submitting alone does not earn a reward.</p>${welcomeState.research_submitted?'<a class="button" href="#research">Check your response</a>':brief?`<p><b>${esc(brief.title)}</b> · ${iq(brief.reward)} if accepted</p><a class="button" href="#respond/${esc(brief.id)}">Read brief and try research</a>`:'<p>No funded brief is available for you right now.</p><a class="outline" href="#research">Browse research</a>'}`)}</div><div class="welcome-actions"><button class="outline" data-welcome-dismiss>${welcomeState.traded&&welcomeState.research_submitted?'Finish welcome journey':'Skip for now'}</button><p class="fine">You can reopen this guide from your wallet. Progress is based on your actual demo activity.</p></div>`;
}
function notificationPage(){return heading('Your notifications','Updates from your shared demo account. No real money is involved.')+`<div class="row between"><p>${inbox.unread} unread · Showing the latest ${inbox.items.length} notifications</p><button class="outline" data-read-notifications="${inbox.through}" ${inbox.unread?'':'disabled'}>Mark all as read</button></div><div class="notification-list">${inbox.items.map(n=>`<article class="panel panel-body notification-item ${n.read?'':'notification-unread'}"><div><span class="tag blue">${n.read?'Read':'Unread'}</span><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p><time datetime="${esc(n.created)}">${esc(new Date(n.created).toLocaleString())}</time></div><a class="outline" href="${esc(n.link)}">${n.link==='#wallet'?'View wallet':'View market'}</a></article>`).join('')||panel('All caught up','<p>New order fills and wallet credits will appear here. Research acceptance includes the reward amount. Waiting orders do not trigger a fill notification.</p>')}</div><p class="fine">These are in-app updates, checked while the exchange is open. They remain in your account when you leave. Earlier activity from before notifications were introduced is not backfilled.</p>`;}
let adminQuery='',adminPageNumber=0;
const adminDate=t=>t?new Date(t*1000).toLocaleString():'Before date tracking';
function adminTable(headers,rows){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">No activity to show.</td></tr>`}</tbody></table></div>`;}
let adminFeedKind='all',adminFeedPaused=false,adminFeedBusy=false;
function usageChart(title,rows,key,money=false){const values=rows.map(d=>d[key]),max=Math.max(1,...values.filter(v=>v!==null)),total=values.reduce((a,v)=>a+(v||0),0);return panel(title,`<strong class="metric-total">${money?iq(total):total.toLocaleString()}</strong><div class="daily-bars" role="img" aria-label="${esc(title)} over fourteen UTC days">${rows.map(d=>`<div class="daily-bar" title="${esc(d.day)}: ${d[key]===null?'Not tracked':money?(d[key]/100).toFixed(2)+' test IQ':d[key]}"><span style="height:${d[key]===null?0:Math.max(d[key]>0?3:0,d[key]/max*100)}%"></span><small>${esc(d.day.slice(8))}</small></div>`).join('')}</div><details><summary>Daily figures</summary>${adminTable(['UTC date',title],rows.map(d=>`<tr><td>${esc(d.day)}</td><td>${d[key]===null?'Not tracked':money?iq(d[key]):d[key]}</td></tr>`))}</details>`);}
async function usagePanel(){const d=await api.request('/admin/summary',{body:{}});return `<section class="admin-usage"><div class="row between"><h2>Usage over the last 14 days</h2><button class="outline" data-admin-refresh>Refresh dashboard</button></div><p>Daily totals in UTC · ${d.unique_active} distinct active users recorded in this period.</p><div class="usage-grid">${usageChart('New signups',d.days,'signups')}${usageChart('Daily active users',d.days,'active')}${usageChart('Trading volume · test IQ',d.days,'volume_units',true)}${usageChart('Research paid · test IQ',d.days,'research_units',true)}</div><p class="fine">Active users are distinct non-admin accounts making authenticated requests each day; the chart total is user-days, not unique people. Tracking began ${esc(adminDate(d.active_tracking_started))}; earlier days are unknown. Signups count self-service accounts with a recorded creation date. Trading volume counts completed fills: both contributions for new Yes/No pairs, or the sale value for existing shares, once per match. Includes market makers. Research payments exclude fees and top-ups. Today is incomplete. Use Refresh dashboard for updated charts.</p></section>`;}
function adminFeedPanel(){return panel('Live demo activity',`<div class="row"><label>Activity<select id="admin-feed-kind">${[['all','All activity'],['signup','New signups'],['trade','Trades'],['research','Research payments'],['topup','IQ top-ups']].map(([v,label])=>`<option value="${v}" ${v===adminFeedKind?'selected':''}>${label}</option>`).join('')}</select></label><button class="outline" data-feed-pause>${adminFeedPaused?'Resume updates':'Pause updates'}</button><button class="outline" data-feed-refresh>Refresh feed</button></div><p id="admin-feed-status" role="status">Loading activity…</p><div id="admin-feed-items"></div><p class="fine">Latest 100 matching events, newest first. Updates every five seconds while this page is open. Trades show completed fills only; waiting orders are not trades. Older signup dates are not reconstructed. All IQ is simulated.</p>`);}
async function refreshAdminFeed(force=false){const target=document.querySelector('#admin-feed-items');if(!target||!session?.operator||adminFeedBusy||(!force&&adminFeedPaused))return;const account=session.subject,kind=adminFeedKind;adminFeedBusy=true;try{const d=await api.request('/admin/activity/query',{body:{kind}});if(document.querySelector('#admin-feed-items')!==target||session?.subject!==account||kind!==adminFeedKind)return;target.innerHTML=d.items.length?d.items.map(e=>`<article class="admin-event"><span class="admin-event-type ${esc(e.kind)}">${esc({signup:'Signup',trade:'Trade',research:'Research',topup:'Top-up'}[e.kind])}</span><div><b>${e.account_link?`<a href="#admin/${esc(e.subject)}">${esc(e.username)}</a>`:esc(e.username)}</b><p>${esc(e.text)}${e.amount_units!==undefined?' <strong>'+iq(e.amount_units)+'</strong>':''}</p>${e.actor_name?`<small>By ${esc(e.actor_name)}</small>`:''}${e.market?` <a href="#${adminMode?'operations':'market'}/${esc(e.market)}">View market</a>`:''}</div><time>${esc(adminDate(e.time))}</time></article>`).join(''):empty('No matching activity yet.');document.querySelector('#admin-feed-status').textContent=`${adminFeedPaused?'Paused':'Auto-updating'} · Last checked ${new Date().toLocaleTimeString()}`;}catch{if(document.querySelector('#admin-feed-items')===target)document.querySelector('#admin-feed-status').textContent='Unable to refresh. Showing the last loaded activity; retrying when updates are on.';}finally{adminFeedBusy=false;}}
main.addEventListener('change',event=>{if(event.target.id==='admin-feed-kind'){adminFeedKind=event.target.value;refreshAdminFeed(true);}});
setInterval(()=>{if(!document.hidden&&!document.querySelector('#dialog').open)refreshAdminFeed();},5000);
async function adminScreen(route){
 if(!session.operator)return heading('Admin access required')+notice('Only authorised demo operators can view or manage accounts.');
 const subject=route.split('/')[1];
 if(!subject){const d=await api.request('/admin/accounts/query',{body:{query:adminQuery,page:adminPageNumber}});return heading('Demo administration','Shared simulated accounts, balances and activity. No real money.')+stats([['Accounts',d.total],['Active access',d.summary.active],['User available IQ',iq(d.summary.available_units)],['User reserved IQ',iq(d.summary.reserved_units)]])+await usagePanel()+adminFeedPanel()+panel('Accounts',`<form id="admin-search" class="row"><label>Search username or account ID<input name="query" maxlength="80" value="${esc(adminQuery)}"></label><button class="button">Search</button><button type="button" class="outline" data-admin-refresh>Refresh</button></form><p>${d.matched} matching accounts · Page ${d.page+1}</p>`+adminTable(['Account','Access','Created','Available','Reserved','Trades','Research','Manage'],d.accounts.map(a=>`<tr><td><b>${esc(a.username)}</b><br><small>${esc(a.signup_type)}${a.operator?' · operator':''}</small></td><td>${esc(a.status)}</td><td>${esc(adminDate(a.created))}</td><td>${iq(a.available_units)}</td><td>${iq(a.reserved_units)}</td><td>${a.trade_count}</td><td>${a.response_count} responses<br>${iq(a.paid_units)} earned</td><td><a class="outline" href="#admin/${esc(a.subject)}">View account</a></td></tr>`))+`<div class="row"><button class="outline" data-admin-page="${Math.max(0,d.page-1)}" ${d.page===0?'disabled':''}>Previous</button><button class="outline" data-admin-page="${d.page+1}" ${(d.page+1)*d.page_size>=d.matched?'disabled':''}>Next</button></div><p class="fine">Balances belong to user accounts; dedicated market-maker funds are shown in Market operations. Older signup dates are not reconstructed.</p>`);}
 const d=await api.request('/admin/accounts/'+encodeURIComponent(subject)),a=d.account;
 return heading(a.username,'Demo account details · '+a.status)+`<a class="outline" href="#admin">All accounts</a> <button class="outline" data-admin-refresh>Refresh</button>`+stats([['Available',iq(a.available_units)],['Reserved',iq(a.reserved_units)],['Research earned',iq(a.paid_units)],['Last login',esc(adminDate(a.last_login))]])+panel('Account access',`<p>Account: ${esc(a.subject)} · ${esc(a.signup_type)} · Created: ${esc(adminDate(a.created))}</p>${a.operator?notice('Operator accounts are protected from changes in this dashboard.'):`<form id="admin-access" data-subject="${esc(a.subject)}"><label>Action<select name="action"><option value="${a.paused?'resume':'pause'}">${a.paused?'Restore sign-in':'Pause sign-in'}</option><option value="signout">Sign out all sessions</option></select></label><label>Reason<input name="reason" minlength="5" maxlength="300" required placeholder="Why are you making this change?"></label><button class="button">Review account change</button></form><p class="fine">These controls affect access only. Existing orders can still fill; holdings, balances and research history remain. Restoring access does not renew expired or revoked access codes.</p>`}`)+panel('Top up simulated IQ',`<p>Add test IQ so this user can keep testing. No payment or real money is involved.</p><form id="admin-topup" data-subject="${esc(a.subject)}" data-username="${esc(a.username)}"><label>IQ to add<input name="amount" type="number" min="0.01" max="10000" step="0.01" required placeholder="1,000"></label><label>Reason<input name="reason" minlength="5" maxlength="300" required placeholder="For another round of demo testing"></label><button class="button">Review top-up</button></form><p class="fine">Maximum 10,000 test IQ per adjustment. The user receives a wallet notification. This does not restore paused or revoked access.</p>`)+panel('IQ adjustment history',adminTable(['When','Operator','Added','Before','After','Reason'],(d.adjustments||[]).map(x=>`<tr><td>${esc(new Date(x.recorded_at).toLocaleString())}</td><td>${esc(x.actor)}</td><td>${iq(x.request.amount)}</td><td>${iq(x.before_units)}</td><td>${iq(x.after_units)}</td><td>${esc(x.request.reason)}</td></tr>`)))+panel('Current holdings',adminTable(['Market','Outcome','Shares','Reserved shares','Cost','Realised P/L'],d.positions.map(p=>`<tr><td>${esc(p.market)}</td><td>${esc(p.side)}</td><td>${p.quantity}</td><td>${p.locked}</td><td>${iq(p.cost)}</td><td>${iq(p.realised)}</td></tr>`)))+panel('Latest orders',adminTable(['Market','Side','Action','Limit','Ordered','Waiting','Status'],d.orders.map(o=>`<tr><td>${esc(o.market)}</td><td>${esc(o.side)}</td><td>${esc(o.direction)}</td><td>${iq(o.price)}</td><td>${o.quantity}</td><td>${o.remaining}</td><td>${esc(o.status)}</td></tr>`)))+panel('Latest trades',adminTable(['Market','Outcome','Action','Shares','Value'],d.trades.map(t=>{const buyer=t.buyer===subject,pair=t.kind==='pair',side=buyer||!pair?t.side:t.side==='yes'?'no':'yes',price=buyer||!pair?t.price:100-t.price;return `<tr><td>${esc(t.market)}</td><td>${esc(side)}</td><td>${buyer||pair?'Bought':'Sold'}</td><td>${t.quantity}</td><td>${iq(price*t.quantity)}</td></tr>`;})))+panel('Research responses',d.responses.map(r=>`<article class="brief-row"><div class="body"><b>${esc(r.title)}</b><p>${esc(r.text)}</p><small>${esc(r.status)} · ${esc(r.sentiment)} · ${iq(r.reward)} if accepted</small></div></article>`).join('')||empty('No responses submitted.'))+panel('Research briefs created',adminTable(['Brief','Status','Places','Reward'],d.briefs.map(b=>`<tr><td>${esc(b.title||b.id)}</td><td>${esc(b.status)}</td><td>${b.count||'—'}</td><td>${iq(b.reward)}</td></tr>`)))+panel('Latest wallet activity',adminTable(['When','Activity','Available balance change'],d.wallet.activity.map(w=>`<tr><td>${esc(new Date(w.recorded_at).toLocaleString())}</td><td>${esc(w.action.replaceAll('_',' '))}</td><td>${iq(w.available_change_units)}</td></tr>`)))+panel('Admin change log',adminTable(['When','Operator','Action','Reason'],d.audit.map(x=>`<tr><td>${esc(adminDate(x.created))}</td><td>${esc(x.actor)}</td><td>${esc(x.action)}</td><td>${esc(x.reason)}</td></tr>`)))+`<p class="fine">Lists show the latest 100 orders, trades, responses, briefs and admin changes; wallet activity shows the latest 50. Passwords, access codes and recovery keys are never displayed.</p>`;
}
function book(v){return `<div class="table-scroll"><table><thead><tr><th>Outcome</th><th>Order</th><th>Limit / share</th><th>Shares waiting</th></tr></thead><tbody>${v.order_book.map(o=>`<tr><td class="${o.side==='yes'?'up':'down'}">${esc(o.side.toUpperCase())}</td><td>${esc(o.direction)}</td><td>${iq(o.price)}</td><td>${o.shares}</td></tr>`).join('')||'<tr><td colspan="4">No orders yet. Your order can wait for another participant.</td></tr>'}</tbody></table></div>`;}
function marketCards(){return `<div class="research-grid">${markets.map(m=>`<article class="panel research-card"><span class="tag blue">${esc(m.id.toUpperCase())} · ${esc(m.status)}</span><h2>${esc(m.question)}</h2><p>${esc(m.rule)}</p><a class="button" href="#market/${esc(m.id)}">View market</a></article>`).join('')||empty('An operator needs to create the first shared market.')}</div>`;}
function chart(v){if(v.bitcoin){const b=v.bitcoin,vs=b.series,lo=Math.min(...vs,b.target_cents)-50,hi=Math.max(...vs,b.target_cents)+50;return `<div class="row between"><b>₿ Simulated BTC: $${(b.price_cents/100).toFixed(2)}</b><strong>${Math.floor(b.remaining/60)}:${String(b.remaining%60).padStart(2,'0')}</strong></div><p>Target: $${(b.target_cents/100).toFixed(2)} · ${esc(v.market.status)} ${esc(v.market.outcome||'')}</p><svg viewBox="0 0 600 200" role="img" aria-label="Shared simulated Bitcoin price"><path d="M20 ${180-(b.target_cents-lo)/(hi-lo)*160}H580" stroke="#204cec" stroke-dasharray="5 5"/><polyline points="${vs.map((n,i)=>`${20+i*560/Math.max(1,vs.length-1)},${180-(n-lo)/(hi-lo)*160}`).join(' ')}" stroke="#f7931a" stroke-width="3" fill="none"/></svg><p class="fine">Fictional replay shared by every account. The server closes trading and settles at five minutes, even if you leave this page.</p>`;}const trades=[...(v.trades||[])].reverse();if(!trades.length)return notice('No trades yet. The chart starts when the first shares match.');const values=trades.map(t=>t.side==='yes'?t.price:100-t.price);const points=values.map((v,i)=>`${20+i*560/Math.max(values.length-1,1)},${180-v*1.6}`).join(' ');return `<svg viewBox="0 0 600 200" role="img" aria-label="Executed Yes share prices, oldest to newest"><path d="M20 20H580M20 100H580M20 180H580" stroke="var(--line)" fill="none"/><polyline points="${points}" fill="none" stroke="#204cec" stroke-width="3"/><text x="20" y="198" fill="currentColor" font-size="12">Executed trades · latest Yes equivalent ${(values.at(-1)/100).toFixed(2)} IQ</text></svg>`;}
function starterPrice(v,side='yes'){const prices=v.order_book.flatMap(o=>o.side===side&&o.direction==='sell'?[o.price]:o.side!==side&&o.direction==='buy'?[100-o.price]:[]);return (prices.length?Math.min(...prices):50)/100;}
function ticket(v){return `<form id="order" data-market="${esc(v.market.id)}"><div class="segmented"><button type="button" data-direction="buy" class="active">Buy</button><button type="button" data-direction="sell">Sell</button></div><input type="hidden" name="direction" value="buy"><input type="hidden" name="side" value="yes"><div class="shared-outcomes"><button type="button" data-side="yes" aria-pressed="true">Yes / Up</button><button type="button" data-side="no" aria-pressed="false">No / Down</button></div><label>Number of shares<input name="shares" type="number" min="1" max="1000000" step="1" value="${guidedMarket===v.market.id?5:10}" required></label><label>Limit price per share (0.01–0.99 IQ)<input name="price" type="number" min="0.01" max="0.99" step="0.01" value="${guidedMarket===v.market.id?starterPrice(v):0.50}" required></label><div class="row">${[10,100,1000,10000].map(n=>`<button type="button" class="outline" data-quick="${n}">${n.toLocaleString()} <small>IQ</small></button>`).join('')}</div><button class="button" ${v.market.status==='open'?'':'disabled'}>Preview order</button><p class="fine rule">Buy: this is the most you will pay per share. Sell: this is the least you will accept. Unfilled shares wait until matched or cancelled. Preview prices can change before confirmation.</p></form>`;}
function ownOrders(v){return v.orders.filter(o=>o.status==='open').map(o=>`<div class="brief-row"><div class="body"><b>${esc(o.direction)} ${esc(o.side)}</b><p>${o.remaining} shares waiting at ${iq(o.price)}</p></div><button class="outline" data-cancel="${esc(o.id)}">Cancel</button></div>`).join('')||empty('No waiting orders.');}
function positionRows(){return views.flatMap(v=>v.positions.map(p=>({v,p}))).filter(({p})=>p.quantity||p.realised).map(({v,p})=>`<tr><td><a href="#market/${esc(v.market.id)}">${esc(v.market.question)}</a><small> · ${esc(p.side)}</small></td><td>${p.quantity} (${p.locked} reserved)</td><td>${iq(p.cost)}</td><td>${iq(p.estimated_sale_units)}<small> for ${p.sellable_now_shares} shares</small></td><td>${iq(p.estimated_sale_pnl_units)}<small> on quoted shares</small></td><td>${iq(p.realised)}</td><td><a class="outline" href="#market/${esc(v.market.id)}">Buy / sell</a></td></tr>`).join('');}
function operationsControls(o){return panel('Bitcoin demo',`<button class="button" data-start-btc>Start a shared five-minute round</button><p class="fine">One round at a time. Fund its maker below to add liquidity.</p>`)+panel('Fund a market maker',`<form id="maker"><label>Market<select name="market">${markets.filter(m=>m.status==='open').map(m=>`<option value="${esc(m.id)}">${esc(m.question)}</option>`).join('')}</select></label><label>Budget from your wallet (IQ)<input name="budget" type="number" min="1" step="0.01" value="100" required></label><label>Maximum committed exposure (IQ)<input name="exposure" type="number" min="1" step="0.01" value="100" required></label><label>Shares per quote<input name="clip" type="number" min="1" max="1000" step="1" value="20" required></label><button class="button">Review funding</button></form><p class="fine">Funded orders only. Prices react after customer orders; profit is not guaranteed. Choose a quote below after funding.</p>`)+o.makers.map(m=>panel(m.owner,stats([['Available',iq(m.available_units)],['Committed',iq(m.committed_exposure_units)],['Inventory cost',iq(m.inventory_cost_units)],['Realised P/L',iq(m.realised_pnl_units)]])+`<form id="quote" data-owner="${esc(m.owner)}"><label>Fair Yes price (IQ)<input name="fair" type="number" min="0.05" max="0.95" step="0.01" value="0.50"></label><label>Spread (IQ)<input name="spread" type="number" min="0.02" max="0.20" step="0.01" value="0.06"></label><button class="button">Review quotes</button></form><button class="outline" data-pause="${esc(m.owner)}">Pause maker and release orders</button>`)).join('')+panel('Close and settle',`<form id="settle"><label>Market<select name="market">${markets.filter(m=>m.status!=='settled').map(m=>`<option value="${esc(m.id)}">${esc(m.question)} · ${esc(m.status)}</option>`).join('')}</select></label><label>Action<select name="outcome"><option value="close">Close trading and release waiting orders</option><option value="yes">Settle Yes</option><option value="no">Settle No</option><option value="invalid">Invalid — return 0.50 IQ per share, no fee</option></select></label><label>Evidence reference<input name="evidence" pattern="[A-Za-z0-9_-]{1,64}" placeholder="demo_result_001"></label><button class="button">Review action</button></form>`);}
function researchCards(owned=false){return studies.filter(s=>s.mine===owned).map(s=>panel(s.title,`<span class="tag">${esc(s.status)}</span><p>${esc(s.objective)}</p><p class="fine">Acceptance: ${esc(s.criteria)}</p><p>${iq(s.reward)} per accepted response · ${s.count} places</p><p class="fine">Audience: ${Object.values(s.audience).map(esc).join(' · ')}</p>${owned?`<p>Budget remaining: ${iq(s.reserved)}</p><a class="button" href="#study/${esc(s.id)}">Review responses</a> <a class="outline" href="#intelligence/${esc(s.id)}">Analyse results</a>`:s.responses.length?`<p>Your response: ${esc(s.responses[0].status)}</p>`:`<a class="button" href="#respond/${esc(s.id)}">Give fictional feedback</a>`}`)).join('')||empty('No briefs to show yet.');}
function studyView(s){if(!s)return empty('Brief not found.');if(!s.mine)return empty('This brief belongs to another buyer.');return heading(s.title,'These are responses submitted by other demo accounts. No sample responses have been added.')+notice('Only the brief owner can see all its responses. Use fictional profiles and feedback in this test.')+`<label>Filter by sentiment<select id="sentiment-filter">${options(['All','Positive','Mixed','Negative'])}</select></label><div id="responses">${s.responses.map(r=>`<article class="panel panel-body" data-sentiment="${esc(r.sentiment)}"><span class="tag">${esc(r.sentiment)} · ${esc(r.status)}</span><p>${esc(r.text)}</p><p class="fine">${Object.values(r.profile).map(esc).join(' · ')}</p>${r.status==='pending'?`<button class="button" data-review="accepted" data-study="${esc(s.id)}" data-response="${esc(r.id)}">Accept and pay ${iq(s.reward)}</button> <button class="outline" data-review="rejected" data-study="${esc(s.id)}" data-response="${esc(r.id)}">Reject</button>`:''}</article>`).join('')||empty('No responses yet.')}</div>${s.status==='open'?`<button class="outline" data-close-study="${esc(s.id)}">Close brief and release unused budget</button>`:''}`;}
async function render(){if(!session)return login();if(session.operator&&!adminMode){location.replace('/exchange/admin.html'+(location.hash||'#admin'));return;}if(adminMode&&!session.operator)return startSession();const run=++generation;let route=location.hash.slice(1)||(adminMode?'admin':'markets');if(adminMode&&!['admin','operations','launch','security'].some(x=>route===x||route.startsWith(x+'/')))route='admin';if(!adminMode&&['admin','operations','launch','security'].some(x=>route===x||route.startsWith(x+'/')))route='markets';try{const [nextWallet,nextMarkets,nextStudies,nextInbox]=await Promise.all([api.wallet(),api.markets(),api.request('/studies'),api.request('/notifications')]);const nextViews=await Promise.all(nextMarkets.markets.map(m=>api.market(m.id)));if(run!==generation)return;inbox=nextInbox;notificationCursor=Math.max(notificationCursor||0,inbox.through);wallet=nextWallet;markets=nextMarkets.markets;studies=nextStudies.studies;views=nextViews;const saved=await api.request('/reports');savedReportIDs=new Set(saved.reports.map(x=>x.report.id));analystState.business={campaigns:studies.filter(s=>s.mine).map(s=>({...s,company:session.subject,responses:s.responses.map(r=>({...r,time:r.time||0}))})),reports:saved.reports.filter(x=>x.kind==='snapshot').map(x=>x.report),fullReports:saved.reports.filter(x=>x.kind==='full').map(x=>x.report)};chrome();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',route.startsWith(a.dataset.nav)));let html='';
if(route==='security'&&adminMode&&session.operator)html=heading('Admin security','Change the password for your administrator account only.')+panel('Change your admin password',`<p>Signed in as <b>${esc(session.username||session.subject)}</b>.</p><form id="admin-password-change" class="admin-password-form"><label>Current admin password<input name="current_password" type="password" autocomplete="current-password" required maxlength="128"></label><label>New admin password<input name="new_password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><p class="fine">Use at least 15 characters. A few unrelated words can make a memorable password.</p><label>Confirm new admin password<input name="confirm_password" type="password" autocomplete="new-password" required minlength="15" maxlength="128"></label><div id="admin-password-error" role="alert" class="error"></div><p>Changing your password signs out all your admin sessions, including this one. Sign in again with your new password. Normal user accounts and IQ balances are unaffected.</p><button class="button">Change password and sign out</button></form><p class="fine">Your new password is not saved to the generated login file. Store it privately. If the connection drops after submitting, try signing in with your new password first.</p>`);
else if(route==='admin'||route.startsWith('admin/'))html=await adminScreen(route);
else if(route==='notifications')html=notificationPage();
else if(route==='welcome'){welcomeState=await api.request('/welcome');html=welcomePage();}
else if(route.startsWith('market/')){view=route.split('/')[1]==='btc'?views.filter(v=>v.bitcoin).sort((a,b)=>b.bitcoin.start-a.bitcoin.start)[0]:views.find(v=>v.market.id===route.split('/')[1]);if(!view)throw Error('Market not found.');html=heading(view.market.question,'Shared orders · prices come from participants and funded market makers.')+`<div class="market-layout"><div class="stack">${panel(view.bitcoin?'Simulated Bitcoin price':'Executed share prices',`<div id="live-chart">${chart(view)}</div>`)}${panel('Live order book',`<div id="live-book">${book(view)}</div><p class="fine rule">Complementary Yes and No buys can match when together they fund 1 IQ per share pair. Selling existing shares needs a buyer for that outcome.</p>`)}${panel('Your waiting orders',ownOrders(view))}${panel('Resolution rule',`<p>${esc(view.market.rule)}</p><p class="fine">Evidence source: ${esc(view.market.evidence_source)} · Settlement fee ${(view.market.fee_bps/100).toFixed(2)}% of gross payout.</p>`)}</div>${panel('Trade IQ shares',(guidedMarket===view.market.id?notice('Your first trade: choose Yes or No, keep the size small, then preview. Nothing is spent until you confirm. You can cancel any waiting remainder from Your waiting orders.')+'<a href="#welcome">Back to your welcome journey</a>':'')+ticket(view))}</div>`;}
else if(route==='positions'){html=heading('My positions','Sale estimates cover only shares with an available buyer. Unquoted shares are not valued at zero.')+stats([['Remaining cost',iq(views.flatMap(v=>v.positions).reduce((a,p)=>a+p.cost,0))],['Quoted sale proceeds',iq(views.flatMap(v=>v.positions).reduce((a,p)=>a+p.estimated_sale_units,0))],['Realised profit / loss',iq(views.flatMap(v=>v.positions).reduce((a,p)=>a+p.realised,0))],['Available wallet',iq(wallet.available_units)]])+panel('Your shares',`<div class="table-scroll"><table><thead><tr><th>Market</th><th>Shares</th><th>Cost remaining</th><th>Sell now</th><th>Estimated P/L</th><th>Realised P/L</th><th>Trade</th></tr></thead><tbody>${positionRows()}</tbody></table></div>`);}
else if(route==='wallet'){html=heading('Your IQ wallet','One shared account for trading and paid research. Cash deposits and withdrawals are disabled.')+stats([['Available',iq(wallet.available_units)],['Reserved',iq(wallet.reserved_units)],['Account',esc(session.subject)],['Asset','IQ only']])+panel('Recorded activity',wallet.activity.map(a=>`<div class="brief-row"><div class="body"><b>${esc(a.action.replaceAll('_',' '))}</b><p>${esc(a.recorded_at)}</p></div>${iq(a.available_change_units)}</div>`).join(''))+`<div class="row"><a class="outline" href="#welcome">Welcome guide</a><button class="outline" data-logout>Sign out</button></div>`;}
else if(route==='business'||route==='business/new'){html=heading('Business workspace','Fund a brief from your IQ wallet, collect responses and pay accepted work.')+notice('Your budget covers participant rewards plus a 25% service fee. Both are charged only when you accept a response; unused budget returns on closure.')+panel('Create a fictional research brief',`<form id="study"><label>Title<input name="title" required minlength="5" maxlength="160"></label><label>Research objective<textarea name="objective" required minlength="30" maxlength="3000"></textarea></label><label>Acceptance criteria<textarea name="criteria" required minlength="20" maxlength="3000"></textarea></label><div class="stats">${profiles(true)}</div><label>Number of responses<input name="count" type="number" min="1" max="500" value="10" required></label><label>Reward per accepted response (IQ)<input name="reward" type="number" min="1" max="100" step="0.01" value="10" required></label><button class="button">Review budget</button></form>`)+`<div class="stack">${researchCards(true)}</div>`;}
else if(route.startsWith('respond/')){const s=studies.find(s=>s.id===route.split('/')[1]);if(!s)throw Error('Brief not found');html=heading(s.title,s.objective)+notice('Use a fictional profile and feedback. Payment is made only after the buyer accepts your response against the stated criteria.')+panel('Submit a response',`<p>${esc(s.criteria)}</p><form id="response" data-study="${esc(s.id)}"><div class="stats">${profiles()}</div><label>Sentiment<select name="sentiment">${options(['Positive','Mixed','Negative'])}</select></label><label>Your fictional experience<textarea name="text" required minlength="30" maxlength="3000"></textarea></label><button class="button">Review response</button></form>`);}
else if(route.startsWith('study/'))html=studyView(studies.find(s=>s.id===route.split('/')[1]));
else if(route==='research')html=heading('Earn IQ through research','Accepted responses are paid from the buyer’s reserved budget into your trading wallet.')+`<div class="stack">${researchCards(false)}</div>`;
else if(route.startsWith('intelligence'))html=briefIntelligencePage(route.split('/')[1]||'briefs').replace('Fictional research in this browser only.','Shared simulated research.').replace('This connected owner-demo view displays small samples and is not a production privacy control.','Only the authenticated brief owner can access its responses.').replace(/href="#business\/((?!new")[^"]+)"/g,'href="#study/$1"');
else if(route.startsWith('operations')||route==='launch'){html=heading('Market operations','Operator access is required to create shared questions or allocate market-maker funds.');if(session.operator){const o=await api.operations();html+=operationsControls(o)+panel('Reconciliation',`<pre>${esc(JSON.stringify(o,null,2))}</pre>`)+panel('Create a question',`<form id="market"><label>Market identifier<input name="market_id" pattern="[a-zA-Z0-9_-]{1,64}" required></label><label>Question<input name="question" required></label><label>Exact settlement rule<textarea name="rule" required></textarea></label><label>Evidence source<input name="evidence_source" required></label><button class="button">Review market</button></form>`);}else html+=empty('Your account can trade and participate in research. An administrator manages shared markets.');}
else html=heading('The intelligence exchange','Every order here belongs to a shared demo account. No browser-generated fills or balances.')+marketCards();main.innerHTML=html;if(document.querySelector('#admin-feed-items'))refreshAdminFeed(true);
}catch(e){error(e);if(e.status!==401)main.innerHTML=heading('Unable to refresh')+notice('The service could not provide current data. No browser balance changes were made. Try refreshing.');}}
function review(title,body,send,payload){attempted=false;pending=new IQPendingAction(send,payload);const dialog=document.querySelector('#dialog');document.querySelector('#dialog-content').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}<p class="fine">Simulated IQ only. A timeout does not mean an action failed: use this same confirmation again to check its result.</p><div class="error" id="confirm-error"></div><div class="modal-actions"><button class="button" id="confirm">Confirm</button></div>`;dialog.showModal();}
main.addEventListener('submit',async event=>{if(event.target.id.startsWith('intel-'))return;event.preventDefault();const form=event.target, f=Object.fromEntries(new FormData(form));try{
if(form.id==='admin-recover'){const message=form.querySelector('#admin-recover-error'),button=form.querySelector('button');message.textContent='';if(f.new_password!==f.confirm_password){message.textContent='The new passwords do not match.';return;}button.disabled=true;try{const result=await api.request('/admin/recover',{body:{username:f.username,recovery_key:f.recovery_key,new_password:f.new_password}});form.reset();session=null;wallet=null;adminRecoverMode=false;login();pending=null;attempted=false;showAdminRecovery(document.querySelector('#dialog'),f.username.trim().toLowerCase(),result.recovery_key);toast('Admin password reset. Save the replacement key, then sign in.');}catch(e){message.textContent=e.status&&e.status<500?e.message:'Unable to confirm recovery. Try logging in with your new password first. If recovery succeeded but the replacement key was lost, the host operator must issue a new recovery key.';}finally{button.disabled=false;}return;}
if(form.id==='admin-password-change'){const message=form.querySelector('#admin-password-error'),button=form.querySelector('button');message.textContent='';if(f.new_password!==f.confirm_password){message.textContent='The new passwords do not match.';return;}if(f.current_password===f.new_password){message.textContent='Choose a different new password.';return;}button.disabled=true;try{await api.request('/admin/password/change',{body:{current_password:f.current_password,new_password:f.new_password}});form.reset();session=null;wallet=null;location.hash='security';login();toast('Admin password changed. Sign in with your new password.');}catch(e){if(e.status===401){form.reset();session=null;login();toast('Your session ended. Try signing in with your new password.');}else message.textContent=e.status&&e.status<500?e.message:'Unable to confirm the result. Try signing in with your new password first; if it fails, use your previous password.';}finally{button.disabled=false;}return;}
if(form.id==='admin-login'){session=await api.request('/admin/session',{body:f});return startSession();}
if(form.id==='admin-search'){adminQuery=f.query;adminPageNumber=0;return render();}
if(form.id==='admin-topup'){const amount=Number(f.amount),amount_units=Math.round(amount*100);if(!Number.isFinite(amount)||amount_units<=0||amount_units>1000000||Math.abs(amount*100-amount_units)>0.000001)throw new Error('Enter between 0.01 and 10,000 IQ, with up to two decimal places.');if(f.reason.trim().length<5)throw new Error('Please give a reason of at least five characters.');return review('Confirm simulated IQ top-up',notice(`Add ${amount.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})} test IQ to ${form.dataset.username}. Reason: ${f.reason.trim()}. The user will receive a notification. No real money is involved.`),b=>api.request(`/admin/accounts/${form.dataset.subject}/topup`,{body:b}),{amount_units,reason:f.reason.trim(),key:uid()});}
if(form.id==='admin-access')return review('Confirm account access change',notice(`${f.action==='pause'?'Pause sign-in and end existing sessions':f.action==='resume'?'Restore sign-in; users must log in again':'End all current sessions'}. Existing orders, holdings and balances remain. Reason: ${f.reason}`),b=>api.request(`/admin/accounts/${form.dataset.subject}/access`,{body:b}),{action:f.action,reason:f.reason,key:uid()});
if(form.id==='account-auth'){
 const mode=form.dataset.mode,button=form.querySelector('.button');
 if(f.confirm_password!==undefined&&f.password!==f.confirm_password){document.querySelector('#auth-error').textContent='The passwords do not match.';return;}
 button.disabled=true;
 try{const body={username:f.username,password:f.password,...(mode==='recover'?{recovery_key:f.recovery_key}:{})};const result=await api.request('/'+(mode==='signup'?'signup':mode==='recover'?'recover':'login'),{body});const recovery=result.recovery_key;delete result.recovery_key;session=result;await startSession();if(recovery)recoveryNotice(f.username.trim().toLowerCase(),recovery,mode==='signup');}catch(e){const errorBox=document.querySelector('#auth-error');if(errorBox)errorBox.textContent=e.message+(mode==='signup'?' If you lost the connection after submitting, try logging in with your chosen username.':'');}finally{button.disabled=false;}return;
}
if(form.id==='login'){session=await api.request('/session',{body:f});await api.rules();return startSession();}
if(form.id==='order'){const body={side:f.side,direction:f.direction,shares:Number(f.shares),price_units:Math.round(Number(f.price)*100),order_id:uid(),key:uid()};const id=form.dataset.market;const p=await api.preview(id,body);const rows=[['Shares expected now',p.filled_shares],['Shares waiting',p.waiting_shares],...(f.direction==='buy'?[['Maximum reserved',iq(p.maximum_reservation_units)],['Expected spend now',iq(p.estimated_spend_units)],['Returned if correct (after fee)',iq(p.estimated_return_if_correct_units)],['Profit if correct',iq(p.estimated_profit_if_correct_units)]]:[['Expected sale proceeds',iq(p.estimated_proceeds_units)],['Estimated realised P/L',iq(p.estimated_realised_pnl_units)]])];return review('Review '+f.direction,`<dl class="summary">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`+notice('Only currently matched shares are included in these payout estimates. Unfilled quantities stay as a limit order. A losing share pays zero.'),b=>api.order(id,b),body);}
if(form.id==='study'){const body={study_id:uid(),title:f.title,objective:f.objective,criteria:f.criteria,count:Number(f.count),reward_units:Math.round(Number(f.reward)*100),audience:Object.fromEntries(Object.keys(profileOptions).map(k=>[k,f[k]])),key:uid()};return review('Fund research',`<p>Reserve ${iq(body.count*(body.reward_units+Math.round(body.reward_units*.25)))} for ${body.count} responses. Unused rewards return when the brief closes. Includes the 25% service fee on accepted work.</p>`,b=>api.request('/studies',{body:b}),body);}
if(form.id==='response'){const body={response_id:uid(),text:f.text,sentiment:f.sentiment,profile:Object.fromEntries(Object.keys(profileOptions).map(k=>[k,f[k]])),key:uid()};return review('Submit fictional feedback',`<p>${esc(f.text)}</p>`,b=>api.request(`/studies/${form.dataset.study}/responses`,{body:b}),body);}
if(form.id==='maker'){const body={owner:'maker_'+uid().replaceAll('-','').slice(0,20),budget_units:Math.round(Number(f.budget)*100),exposure_limit_units:Math.round(Number(f.exposure)*100),clip:Number(f.clip),key:uid()};return review('Fund market maker',`<p>Move ${iq(body.budget_units)} from your wallet into this maker's dedicated account. Exposure cap: ${iq(body.exposure_limit_units)}.</p>`,b=>api.request(`/markets/${f.market}/maker`,{body:b}),body);}
if(form.id==='quote')return review('Update funded quotes',notice('The maker replaces its waiting orders within its budget and exposure cap.'),b=>api.request(`/makers/${form.dataset.owner}/quote`,{body:b}),{fair_yes:Math.round(Number(f.fair)*100),spread:Math.round(Number(f.spread)*100),key:uid()});
if(form.id==='settle'){const close=f.outcome==='close';return review(close?'Close trading':'Settle market',notice(close?'All waiting orders will be cancelled; matched shares remain until settlement.':`Resolve ${f.outcome.toUpperCase()} using ${f.evidence}. Only closed markets can settle. Winning payouts go to shared wallets after the disclosed fee.`),b=>api.request(`/markets/${f.market}/${close?'close':'settle'}`,{body:b}),close?{key:uid()}:{outcome:f.outcome,evidence_ref:f.evidence,key:uid()});}
if(form.id==='market')return review('Create shared market',`<p>${esc(f.question)}</p><p>${esc(f.rule)}</p>`,b=>api.request('/markets',{body:b}),{...f,fee_bps:200,key:uid()});
}catch(e){error(e);}});
main.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;try{if(el.hasAttribute('data-admin-recover')){adminRecoverMode=el.dataset.adminRecover==='open';return login();}if(el.hasAttribute('data-feed-refresh'))return refreshAdminFeed(true);if(el.hasAttribute('data-feed-pause')){adminFeedPaused=!adminFeedPaused;el.textContent=adminFeedPaused?'Resume updates':'Pause updates';document.querySelector('#admin-feed-status').textContent=adminFeedPaused?'Updates paused. Refresh manually or resume.':'Resuming updates…';if(!adminFeedPaused)refreshAdminFeed(true);return;}if(el.hasAttribute('data-admin-refresh'))return render();if(el.hasAttribute('data-admin-page')){adminPageNumber=Number(el.dataset.adminPage);return render();}if(el.hasAttribute('data-read-notifications')){el.disabled=true;try{inbox=await api.request('/notifications/read',{body:{through:Number(el.dataset.readNotifications)}});await render();}finally{el.disabled=false;}return;}if(el.hasAttribute('data-welcome-dismiss')){el.disabled=true;try{welcomeState=await api.request('/welcome/dismiss',{body:{}});location.hash='markets';}finally{el.disabled=false;}return;}if(el.dataset.guidedMarket){guidedMarket=el.dataset.guidedMarket;location.hash='market/'+guidedMarket;return;}if(el.dataset.auth){authMode=el.dataset.auth;return login();}if(el.dataset.side){const f=el.closest('form');f.elements.side.value=el.dataset.side;if(guidedMarket===view?.market.id)f.elements.price.value=starterPrice(view,el.dataset.side);f.querySelectorAll('[data-side]').forEach(b=>b.setAttribute('aria-pressed',String(b===el)));}if(el.dataset.quick){const f=el.closest('form');if(f.elements.direction.value==='sell'){toast('Enter the number of shares you want to sell.');return;}f.elements.shares.value=Math.floor(Number(el.dataset.quick)/Number(f.elements.price.value));}if(el.dataset.direction){const form=el.closest('form');form.elements.direction.value=el.dataset.direction;form.querySelectorAll('[data-direction]').forEach(b=>b.classList.toggle('active',b===el));}
if(el.hasAttribute('data-start-btc'))review('Start shared Bitcoin round',notice('Starts a five-minute fictional replay for all accounts. It settles automatically using its final simulated price.'),b=>api.request('/bitcoin',{body:b}),{key:uid()});
if(el.dataset.pause)review('Pause maker',notice('Cancels its waiting orders. Existing holdings remain exposed until sold or settled.'),b=>api.request(`/makers/${el.dataset.pause}/pause`,{body:b}),{key:uid()});
if(el.dataset.cancel)review('Cancel remaining order',notice('Only the unfilled portion will be cancelled. Reserved IQ or shares will be released.'),b=>api.cancel(b.id,b.key),{id:el.dataset.cancel,key:uid()});
if(el.dataset.review)review(el.dataset.review==='accepted'?'Accept and pay response':'Reject response',notice('This decision applies to the response shown. Payments are recorded once in the shared ledger.'),b=>api.request(`/studies/${el.dataset.study}/responses/${el.dataset.response}/review`,{body:b}),{decision:el.dataset.review,key:uid()});
if(el.dataset.closeStudy)review('Close brief',notice('All pending responses need a decision first. Unused budget will return to your wallet.'),b=>api.request(`/studies/${el.dataset.closeStudy}/close`,{body:b}),{key:uid()});
if(el.hasAttribute('data-logout')){const r=await fetch('/api/iq/session',{method:'DELETE',credentials:'same-origin'});if(!r.ok)throw Error('Sign out failed. Please retry.');session=null;login();}
}catch(e){error(e);}});
document.querySelector('#dialog').addEventListener('click',async e=>{if(e.target.hasAttribute('data-recovery-saved')){document.querySelector('#dialog').close();document.querySelector('#dialog-content').innerHTML='';return;}if(e.target.closest('.close')){if(attempted&&pending&&!pending.complete){toast('Finish or retry the reviewed action before closing.');return;}document.querySelector('#dialog').close();}if(e.target.id!=='confirm'||!pending)return;const b=e.target;attempted=true;b.disabled=true;try{await pending.confirm();document.querySelector('#dialog').close();toast('Recorded in the shared ledger.');await render();}catch(err){document.querySelector('#confirm-error').textContent=err.message;b.textContent='Retry same confirmation';if(err.definitive){pending=null;b.hidden=true;}}finally{b.disabled=false;}});
document.querySelector('#dialog').addEventListener('cancel',e=>{if(attempted&&pending&&!pending.complete)e.preventDefault();});
