setInterval(async()=>{if(!session||document.hidden||document.querySelector('#dialog').open)return;try{const account=session.subject;const fresh=await api.request('/notifications');if(session?.subject!==account)return;if(notificationCursor!==null&&fresh.items.some(n=>n.seq>notificationCursor&&!n.read))toast('New demo account update. Open Notifications to see it.');notificationCursor=Math.max(notificationCursor||0,fresh.through);const notificationsChanged=JSON.stringify(inbox)!==JSON.stringify(fresh);inbox=fresh;notificationBadge();if(location.hash==='#notifications'){if(notificationsChanged)main.innerHTML=notificationPage();wallet=await api.wallet();chrome();return;}if(location.hash==='#positions'||(location.hash.startsWith('#operations')&&!document.activeElement?.matches('input,select,textarea'))){await render();return;}wallet=await api.wallet();chrome();const id=location.hash.startsWith('#market/')?view?.market.id:null;if(id&&document.querySelector('#live-book')){const latest=await api.market(id);if(location.hash===`#market/${id}`||location.hash==='#market/btc'){document.querySelector('#live-book').innerHTML=book(latest);document.querySelector('#live-chart').innerHTML=chart(latest);view=latest;if(latest.market.status!=='open'){const submit=document.querySelector('#order button[type=submit],#order>.button');if(submit)submit.disabled=true;}}}}catch{/* Explicit action/refresh reports service failure; never mutate balances locally. */}},5000);

